with flattened as (select id, effective_from, currency, explode(tier_limits) as val from price_tiers) select case when val >= 88 then 'PREMIUM' else 'STANDARD' end as val_tier, currency, round(sum(val) / nullif(count(case when currency = 'THB' then 1 end), 0), 2) as val_per_thb, count(case when currency = 'USD' then 1 end) as usd_count, count(*) as num_rows, round(sum(val) / nullif(count(case when currency = 'USD' then 1 end), 0), 2) as val_per_usd, count(distinct currency) as distinct_currencies, round(sum(val) / nullif(count(case when currency = 'EUR' then 1 end), 0), 2) as val_per_eur from flattened group by case when val >= 88 then 'PREMIUM' else 'STANDARD' end, currency order by num_rows asc nulls last;
